ount_amount ?? 0))) }}</strong></div><div class="small">مبلغ نهایی گروه: <strong data-group-final>{{ $rial(max($groupGross - $groupItems->sum(fn($item)=>(int)($item->line_discount_amount ?? 0)), 0)) }}</strong></div></div></div>@endforeach</div></div><div class="row g-3 mb-3"><div class="col-md-4"><label class="form-label">نوع تخفیف کلی</label><select name="invoice_discount_type" class="form-select" data-invoice-discount-type><option value="none" @selected($currentInvoiceDiscountType==='none')>بدون تخفیف</option><option value="amount" @selected($currentInvoiceDiscountType==='amount')>مبلغ ثابت</option><option value="percent" @selected($currentInvoiceDiscountType==='percent')>درصدی</option></select></div><div class="col-md-4"><label class="form-label" data-invoice-discount-value-label>مقدار تخفیف کلی</label><input type="text" inputmode="numeric" name="invoice_discount_value" class="form-control js-money" value="{{ $fmtMoney($currentInvoiceDiscountValue) }}" data-invoice-discount-value><div class="small text-muted" data-invoice-discount-hint>تخفیف کلی پس از تخفیف محصول محاسبه می‌شود.</div></div><div class="col-md-4 small"><div>جمع ناخالص: <strong data-summary-gross>{{ $rial($totals['subtotal_before_discount'] ?? 0) }}</strong></div><div>تخفیف محصول: <strong data-summary-product-discount>{{ $rial($totals['items_discount'] ?? 0) }}</strong></div><div>تخفیف کلی: <strong data-summary-invoice-discount>{{ $rial($discountEditorState['invoice_discount']['amount'] ?? $order->invoice_discount_amount ?? 0) }}</strong></div><div>مجموع کل تخفیف: <strong data-summary-total-discount>{{ $rial($totals['total_discount'] ?? 0) }}</strong></div><div>هزینه ارسال: <strong data-summary-shipping data-value="{{ (int)($totals['shipping'] ?? 0) }}">{{ $rial($totals['shipping'] ?? 0) }}</strong></div><div>مبلغ قابل پرداخت: <strong data-summary-grand-total>{{ $rial($totals['grand_total'] ?? 0) }}</strong></div></div></div><label for="edit_reason" class="form-label">دلیل ویرایش <span class="text-danger">*</span></label><textarea id="edit_reason" name="edit_reason" rows="3" class="form-control {{ $errors->has('edit_reason') ? 'is-invalid' : '' }}" required minlength="3" maxlength="1000" placeholder="مثلاً: اصلاح قیمت گارد تدی طبق اعلام واحد مالی">{{ old('edit_reason') }}</textarea>@error('edit_reason')<div class="invalid-feedback">{{ $message }}</div>@enderror</div>
