<script>
const financeEditForm=document.querySelector('#financeEditForm');
const digits=s=>String(s||'').replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/[^0-9]/g,'');
const numberValue=v=>Number(digits(v)||0);
const fmtPlain=n=>Number(numberValue(n)).toLocaleString('en-US');
const fmt=n=>Number(Math.max(0,Number(n)||0)).toLocaleString('en-US')+' ریال';
const setText=(selector,value,root=document)=>{const el=root.querySelector(selector); if(el) el.textContent=value;};
const syncDiscountInputMode=(typeEl,valueEl,labelEl,hintEl)=>{if(!typeEl||!valueEl)return; const isPercent=typeEl.value==='percent'; valueEl.classList.toggle('js-money',!isPercent); valueEl.dataset.percentInput=isPercent?'1':'0'; if(isPercent){const clamped=Math.min(numberValue(valueEl.value),100); valueEl.value=clamped?String(clamped):''; if(labelEl)labelEl.textContent='درصد تخفیف محصول'; if(hintEl)hintEl.textContent='درصد بدون ریال و حداکثر ۱۰۰ است.';}else{valueEl.value=fmtPlain(valueEl.value); if(labelEl)labelEl.textContent='مبلغ تخفیف محصول'; if(hintEl)hintEl.textContent='مبلغ با جداکننده سه‌رقمی وارد می‌شود و در Backend به ناخالص گروه Clamp می‌شود.';}};
function allocatedDiscounts(rows,discountAmount,groupGross){let allocated=0;const positive=rows.filter(r=>r.gross>0);positive.forEach((row,index)=>{let share=index===positive.length-1?discountAmount-allocated:Math.floor(discountAmount*row.gross/Math.max(groupGross,1));share=Math.min(Math.max(share,0),row.gross);row.discount=share;allocated+=share;});rows.filter(r=>r.gross<=0).forEach(r=>r.discount=0);}
function recalculateFinanceEditor(){if(!financeEditForm)return;const rows=[...financeEditForm.querySelectorAll('[data-finance-item-row]')].map(row=>{const quantity=numberValue(row.querySelector('.js-qty')?.value);const price=numberValue(row.querySelector('.js-price')?.value);return{row,productId:String(row.dataset.productId||''),gross:quantity*price,discount:0};});const groups=new Map();rows.forEach(r=>{if(!groups.has(r.productId))groups.set(r.productId,[]);groups.get(r.productId).push(r);});let grossSubtotal=0,productDiscount=0;groups.forEach((groupRows,productId)=>{const groupGross=groupRows.reduce((sum,r)=>sum+r.gross,0);grossSubtotal+=groupGross;const card=financeEditForm.querySelector(`[data-product-discount-group][data-product-id="${CSS.escape(productId)}"]`);const typeEl=card?.querySelector('[data-product-discount-type]');const valueEl=card?.querySelector('[data-product-discount-value]');syncDiscountInputMode(typeEl,valueEl,card?.querySelector('[data-product-discount-value-label]'),card?.querySelector('[data-product-discount-hint]'));const type=typeEl?.value==='percent'?'percent':'amount';const rawValue=numberValue(valueEl?.value);const value=type==='percent'?Math.min(rawValue,100):rawValue;let amount=type==='percent'?Math.floor(groupGross*value/100):value;amount=Math.min(Math.max(amount,0),groupGross);allocatedDiscounts(groupRows,amount,groupGross);const allocated=groupRows.reduce((sum,r)=>sum+r.discount,0);productDiscount+=allocated;if(card){setText('[data-group-gross]',fmt(groupGross),card);setText('[data-group-discount-type]',type==='percent'?'درصد':'مبلغ',card);setText('[data-group-discount-value]',type==='percent'?String(value):fmt(value),card);setText('[data-group-discount-amount]',fmt(allocated),card);setText('[data-group-final]',fmt(Math.max(groupGross-allocated,0)),card);}});rows.forEach(({row,gross,discount})=>{const lineDiscount=row.querySelector('[data-line-discount]'); if(lineDiscount){lineDiscount.textContent=fmt(discount); lineDiscount.dataset.value=String(discount);} setText('[data-line-gross]',fmt(gross),row); setText('[data-line-net]',fmt(Math.max(gross-discount,0)),row);});const invoiceTypeEl=financeEditForm.querySelector('[data-invoice-discount-type]');const invoiceValueEl=financeEditForm.querySelector('[data-invoice-discount-value]');const invoiceType=invoiceTypeEl?.value||'none';const subtotalAfterProductDiscount=Math.max(grossSubtotal-productDiscount,0);let invoiceValue=numberValue(invoiceValueEl?.value);if(invoiceType==='percent'){invoiceValue=Math.min(invoiceValue,100); if(invoiceValueEl) invoiceValueEl.value=invoiceValue?String(invoiceValue):'';}else if(invoiceValueEl){invoiceValueEl.value=invoiceType==='none'?'':fmtPlain(invoiceValueEl.value);}let invoiceDiscount=0;if(invoiceType==='amount') invoiceDiscount=Math.min(invoiceValue,subtotalAfterProductDiscount);if(invoiceType==='percent') invoiceDiscount=Math.floor(subtotalAfterProductDiscount*invoiceValue/100);const shipping=numberValue(financeEditForm.querySelector('[data-summary-shipping]')?.dataset.value);const totalDiscount=productDiscount+invoiceDiscount;const grandTotal=Math.max(grossSubtotal-totalDiscount,0)+shipping;setText('[data-summary-gross]',fmt(grossSubtotal),financeEditForm);setText('[data-summary-product-discount]',fmt(productDiscount),financeEditForm);setText('[data-summary-invoice-discount]',fmt(invoiceDiscount),financeEditForm);setText('[data-summary-total-discount]',fmt(totalDiscount),financeEditForm);setText('[data-summary-shipping]',fmt(shipping),financeEditForm);setText('[data-summary-grand-total]',fmt(grandTotal),financeEditForm);}
financeEditForm?.addEventListener('input',e=>{if(e.target.matches('.js-money,.js-price'))e.target.value=fmtPlain(e.target.value);recalculateFinanceEditor();});
financeEditForm?.addEventListener('change',recalculateFinanceEditor);
recalculateFinanceEditor();
@if($errors->has('edit_reason'))document.getElementById('edit_reason')?.focus();@endif
financeEditForm?.addEventListener('submit',e=>{const b=e.submitter;if(b&&b.value==='save_and_finalize'){const m=e.currentTarget.querySelector('input[name="_method"]'); if(m) m.value='POST';} if(b){b.disabled=true;b.innerHTML='<span class="spinner-border spinner-border-sm"></span> در حال ذخیره';}});
</script>
@endsection
